        $line = fgets(STDIN);
        $line = trim($line);
        $row = array_map('intval', explode(' ', $line));
        $grid[$i] = $row;
    }

    $total = $n * $m;
    $numPairs = $total / 2;

    // Find positions of each shoe
    $positions = []; // positions[pair] = [pos1, pos2]
    for ($i = 0; $i < $n; $i++) {
        for ($j = 0; $j < $m; $j++) {
            $pair = $grid[$i][$j];
            $pos = $i * $m + $j;
            if (!isset($positions[$pair])) {
                $positions[$pair] = [];
            }
            $positions[$pair][] = $pos;
        }
    }

    // For each pair, check if they are adjacent
    // If not adjacent, we need to move at least one shoe
    // The minimum number of shoes to move is the number of pairs that are not adjacent

    $minMoves = 0;
    for ($pair = 1; $pair <= $numPairs; $pair++) {
        if (!isset($positions[$pair]) || count($positions[$pair]) != 2) {
            continue;
        }
        $pos1 = $positions[$pair][0];
        $pos2 = $positions[$pair][1];

        $r1 = intdiv($pos1, $m);
        $c1 = $pos1 % $m;
        $r2 = intdiv($pos2, $m);
        $c2 = $pos2 % $m;

        $dist = abs($r1 - $r2) + abs($c1 - $c2);
